mapper.select:
select bf.*,bc.short_name from b_local_file bf inner join b_marketing_customer bc on bc.api_code = bf.api_code where file_type in ('qiqi','xiecheng','yiqianbao','dianxiao','halo')

    and (
    bf.cid like concat("%", #{search},"%")
    or bc.short_name like concat("%", #{search},"%"))


      and bf.create_time >=#{uploadStartTime} 


      and bf.create_time <#{uploadEndTime} 



    and bf.file_type = #{fileType}


order by bmt.create_time desc,bmt.id desc
